# -*- coding: utf-8 -*-
# (speaker, spanish, korean); speaker None => stage direction, "#" => scene heading (neither is a turn)
L, R, N, G = "Lucas", "Ramón", "Sra. Navarro", "Alejandra"
D = [
("#", "Escena 1 · Lunes, 8:10 · En el coche de Ramón, carretera de Onda a Castellón", "장면 1 · 월요일 오전 8시 10분 · 라몬의 차 안, 온다에서 카스테욘으로 가는 길"),
(None, "Lunes 10 de febrero. Ramón Segarra, el director financiero, conduce un coche gris muy limpio. En el salpicadero, una carpeta azul. Lucas va de copiloto con su portátil sobre las rodillas.", "2월 10일 월요일. 재무이사 라몬 세가라가 아주 깨끗한 회색 차를 몬다. 대시보드 위에 파란 서류철이 있다. 루카스는 노트북을 무릎에 올리고 조수석에 앉아 있다."),
(R, "Cierra eso, por favor. En mi coche no se abren ordenadores. Me marean.", "그거 좀 닫아 줘요. 내 차에선 노트북 안 열어요. 멀미 나거든요."),
(L, "Perdón. Iba a tomar notas.", "죄송해요. 메모하려고 했어요."),
(R, "Toma notas con la cabeza. Tenemos cuarenta minutos hasta el banco. Te voy a contar en cuarenta minutos lo que Vicente no te va a contar en cuarenta comidas.", "머리로 메모해요. 은행까지 40분이에요. 비센테가 밥 마흔 번 먹으면서도 안 해 줄 얘기를 40분 안에 해 줄 거예요."),
(L, "Te escucho.", "듣고 있어요."),
(R, "Primera cifra: sesenta y dos millones. Es lo que facturamos el año pasado. Hace cuatro años eran setenta y uno.", "첫 번째 숫자: 6,200만. 작년 매출이에요. 4년 전엔 7,100만이었어요."),
(L, "O sea, hemos perdido casi un trece por ciento.", "그러니까 거의 13%가 줄었네요."),
(R, "Un doce coma siete. Aquí no redondeamos. Segunda cifra: el gas. ¿Cuánto crees que gastamos al año?", "12.7%. 여기선 반올림 안 해요. 두 번째 숫자: 가스. 1년에 얼마 쓸 것 같아요?"),
(L, "No sé... ¿Cuatro millones?", "글쎄요… 400만?"),
(R, "Antes de la crisis, cuatro y medio. El año pasado, casi nueve. Es el doble, como te dijo Pepe.", "위기 전엔 450만. 작년엔 거의 900만. 페페가 말한 대로 두 배죠."),
(L, "¿Nueve millones? Eso es más del catorce por ciento de la facturación.", "900만이요? 그럼 매출의 14%가 넘잖아요."),
(R, "Catorce coma cinco. Bien calculado. Para el que viene de una consultora, no está mal.", "14.5%. 계산 잘했네요. 컨설팅 회사 출신치고 나쁘지 않아요."),
(L, "Gracias. En la consultora hacíamos estas cuentas todo el día.", "고마워요. 컨설팅 회사에선 하루 종일 이런 계산을 했거든요."),
(R, "Ya. Pero aquí las cuentas tienen nombre y apellidos: los de cada persona que trabaja en la fábrica.", "그렇겠죠. 하지만 여기선 숫자마다 이름과 성이 붙어 있어요. 공장에서 일하는 사람 하나하나의 이름이요."),
(L, "¿Y el beneficio?", "이익은요?"),
(R, "Ahí viene la tercera cifra. Este año vamos a cerrar con un resultado de explotación de un millón doscientos mil. Hace cuatro años eran seis.", "거기서 세 번째 숫자가 나와요. 올해 영업이익은 120만으로 마감할 거예요. 4년 전엔 600만이었고요."),
(L, "Un millón doscientos. Sobre sesenta y dos millones es menos de un dos por ciento.", "120만이라. 6,200만 중에 2%도 안 되네요."),
(R, "Uno coma nueve. Es lo que ganamos por cada cien euros que vendemos: un euro y noventa céntimos.", "1.9%. 100유로 팔 때마다 버는 게 1유로 90센트라는 거예요."),
(L, "Con ese margen, cualquier error nos pone en pérdidas.", "그 마진이면 실수 하나로 적자가 나겠네요."),
(R, "Exacto. Y por eso no me gustan las aventuras.", "바로 그거예요. 그래서 내가 모험을 안 좋아하는 거고요."),
(L, "¿Llamas aventura a México?", "멕시코를 모험이라고 부르는 거예요?"),
(R, "Llamo aventura a todo lo que no se puede cobrar en sesenta días.", "60일 안에 돈을 못 받는 건 다 모험이라고 부르죠."),
(L, "Muchos clientes nacionales pagan a noventa días.", "국내 고객도 90일 뒤에 결제하는 데가 많잖아요."),
(R, "Y por eso tenemos una póliza de crédito. Que es justo lo que vamos a renovar hoy.", "그래서 당좌대출 한도가 있는 거죠. 오늘 갱신하러 가는 게 바로 그거고요."),
(L, "¿De cuánto es la póliza?", "한도가 얼마예요?"),
(R, "Cinco millones. Y ahora mismo usamos casi cuatro.", "500만. 그리고 지금 거의 400만을 쓰고 있어요."),
(L, "¿Cuatro de cinco? Eso es un ochenta por ciento.", "500 중에 400이요? 80%네요."),
(R, "Un setenta y ocho. Pero sí, vamos muy justos.", "78%. 하지만 맞아요, 아주 빠듯해요."),
(None, "Un camión de baldosas los adelanta. Ramón señala la carretera.", "타일을 실은 트럭이 그들을 추월한다. 라몬이 도로를 가리킨다."),
(R, "¿Ves esos camiones? Por esta carretera pasan cientos al día. Casi todos van al puerto de Valencia o de Castellón. Casi todos son de vecinos que exportan el setenta por ciento.", "저 트럭들 보여요? 이 길로 하루에 수백 대가 지나가요. 거의 다 발렌시아나 카스테욘 항구로 가요. 거의 다 70%를 수출하는 이웃 회사들 거고요."),
(L, "Entonces sabes que exportar es posible.", "그럼 수출이 가능하다는 건 아시잖아요."),
(R, "Sé que es posible para quien sabe hacerlo. Nosotros no sabemos. Todavía.", "할 줄 아는 사람한테는 가능하다는 걸 알죠. 우린 할 줄 몰라요. 아직은."),
(L, "Para eso estoy aquí.", "그러라고 제가 여기 있는 거잖아요."),
(R, "Ya. Pues te digo lo que cuesta. Si mañana Vicente decide encender el horno tres, solo para calentarlo gastamos unos ochenta mil euros de gas.", "그렇죠. 그럼 비용을 말해 줄게요. 내일 비센테가 3번 가마를 켜기로 하면, 데우는 데만 가스비가 8만 유로쯤 들어요."),
(L, "¿Solo para calentarlo?", "데우는 데만요?"),
(R, "Dos días hasta llegar a temperatura. Y luego, encendido, unos doscientos cincuenta mil al mes entre gas, electricidad y personal.", "온도까지 올리는 데 이틀. 그다음엔 켜 둔 채로 가스, 전기, 인건비 합쳐서 한 달에 25만 정도."),
(L, "Entonces solo tiene sentido si hay pedidos para varios meses.", "그럼 몇 달 치 주문이 있을 때만 의미가 있겠네요."),
(R, "Para tres meses seguidos, como mínimo. Si lo enciendes para un mes y lo apagas, pierdes dinero. Si lo enciendes por un cliente que luego no paga, pierdes la empresa.", "최소 석 달 연속이요. 한 달 켰다가 끄면 돈을 잃고, 나중에 돈을 안 내는 고객 때문에 켜면 회사를 잃어요."),
(L, "¿Lo dices por algo en concreto?", "뭔가 구체적인 일 때문에 하시는 말씀이에요?"),
(R, "(un silencio) Lo digo por experiencia. En 2009...", "(침묵) 경험에서 하는 말이에요. 2009년에…"),
(L, "¿En 2009?", "2009년에요?"),
(R, "Nada. Otro día. Ya llegamos. Aparca tú las preguntas, que yo aparco el coche.", "아무것도 아니에요. 다음에. 다 왔네요. 질문은 당신이 세워 둬요. 차는 내가 세울 테니."),

("#", "Escena 2 · 9:00 · Oficina del banco, Castellón", "장면 2 · 오전 9시 · 카스테욘, 은행 지점"),
(None, "Un despacho con una ventana a la plaza. La señora Navarro, directora de la oficina de empresas, unos cincuenta años, los recibe con una sonrisa profesional.", "광장 쪽으로 창이 난 사무실. 기업 고객 담당 지점장 나바로 씨는 쉰 살쯤 됐고, 사무적인 미소로 그들을 맞는다."),
(N, "Ramón, buenos días, cuánto tiempo. Y usted debe de ser el nuevo responsable de exportación.", "라몬, 안녕하세요, 오랜만이네요. 그리고 이분이 새 수출 책임자시겠군요."),
(L, "Lucas Ferrer, encantado. Ramón me ha pedido que lo acompañe.", "루카스 페레르입니다, 반갑습니다. 라몬이 동행해 달라고 해서요."),
(N, "Me parece muy bien. Siéntense, por favor. Ramón, como sabes, la póliza de crédito vence el treinta y uno de marzo.", "아주 좋네요. 앉으세요. 라몬, 아시다시피 당좌대출 한도가 3월 31일에 만기예요."),
(R, "Lo sé. Venimos a renovarla. Los mismos cinco millones, si es posible.", "알아요. 갱신하러 왔어요. 가능하면 똑같이 500만으로요."),
(N, "Para eso necesito entender cómo va a ir este año. El comité de riesgos me va a preguntar por tres cosas: las ventas, el stock y el gas.", "그러려면 올해가 어떻게 될지 이해해야 해요. 리스크 위원회에서 세 가지를 물을 거예요. 매출, 재고, 가스."),
(R, "Las ventas, las mismas que el año pasado, más o menos. El gas lo tenemos cubierto con un contrato a precio fijo hasta diciembre.", "매출은 작년과 대충 비슷할 거예요. 가스는 12월까지 고정가 계약으로 묶어 놨고요."),
(N, "Eso es una buena noticia. ¿Y el stock? En el último balance tenían casi once millones de euros en existencias.", "그건 좋은 소식이네요. 재고는요? 지난 재무제표에 재고자산이 거의 1,100만 유로였어요."),
(R, "Sí. Es lo que más nos preocupa.", "네. 그게 제일 걱정이에요."),
(N, "A nosotros también. Once millones de euros en baldosas son once millones que no están en la cuenta.", "저희도 그래요. 타일로 묶인 1,100만 유로는 계좌에 없는 1,100만 유로니까요."),
(R, "Por eso este año vamos a vender stock antiguo con descuento en Portugal. Ya hemos empezado.", "그래서 올해 포르투갈에 오래된 재고를 할인해서 팔 거예요. 이미 시작했고요."),
(N, "¿Cuánto esperan liberar?", "얼마나 털어 낼 생각이에요?"),
(R, "Un millón y medio, si va bien.", "잘되면 150만."),
(N, "Lo apunto. Al comité le va a gustar.", "적어 둘게요. 위원회가 좋아하겠네요."),
(L, "Si me permite, señora Navarro, parte de la solución puede ser la exportación.", "실례지만, 나바로 씨, 해법의 일부는 수출일 수 있어요."),
(N, "Le escucho. Cuénteme.", "말씀하세요. 듣고 있어요."),
(L, "La semana pasada recibimos una consulta de una empresa de Monterrey, en México. Un hotel y dos torres de viviendas. Unos sesenta mil metros cuadrados en la primera fase.", "지난주에 멕시코 몬테레이의 한 회사에서 문의가 왔어요. 호텔 하나와 주거용 타워 두 동이요. 1단계로 6만 제곱미터 정도예요."),
(N, "¿Sesenta mil? ¿A qué precio, más o menos?", "6만이요? 대략 얼마에요?"),
(L, "Todavía no hemos hecho la oferta. Pero, para que se haga una idea, podría ser un pedido de entre un millón y un millón y medio de euros.", "아직 견적을 안 냈어요. 하지만 감을 잡으시라고 말씀드리면, 100만에서 150만 유로 사이의 주문이 될 수 있어요."),
(R, "(seco) Si sale. Y si pagan.", "(건조하게) 성사되면요. 그리고 돈을 내면."),
(N, "Ramón tiene razón. ¿Qué forma de pago van a proponer?", "라몬 말이 맞아요. 결제 방식은 뭘로 제안하실 거예요?"),
(L, "Eso es lo que quería preguntarle. ¿Qué nos recomienda?", "그게 여쭤보고 싶었던 거예요. 뭘 추천하시나요?"),
(N, "Para un primer pedido, con un cliente nuevo y en un país nuevo, yo no aceptaría pago a plazo. Lo más seguro es un anticipo y una carta de crédito para el resto.", "첫 주문이고, 새 고객에 새 나라라면 저라면 외상은 안 받아요. 가장 안전한 건 선수금에 나머지는 신용장이에요."),
(L, "¿Una carta de crédito confirmada?", "확인 신용장이요?"),
(N, "Confirmada por un banco español, si es posible. Así, si el banco mexicano no paga, paga el confirmador. Nosotros podemos hacerlo.", "가능하면 스페인 은행이 확인한 걸로요. 그러면 멕시코 은행이 안 내도 확인 은행이 내니까요. 저희가 해 드릴 수 있어요."),
(R, "¿Y cuánto cuesta eso?", "그건 얼마나 들어요?"),
(N, "Depende del país y del banco emisor. Para México, con un banco de primera línea, entre el cero coma cinco y el uno por ciento del importe.", "나라와 개설 은행에 따라 달라요. 멕시코면 일류 은행 기준으로 금액의 0.5%에서 1% 사이예요."),
(L, "Sobre un millón de euros serían entre cinco y diez mil euros.", "100만 유로면 5천에서 1만 유로 사이겠네요."),
(N, "Exacto. Es el precio de dormir tranquilos. También existe el seguro de crédito a la exportación, por si prefieren trabajar con pago aplazado más adelante.", "맞아요. 편히 자는 값이죠. 나중에 외상 거래를 하고 싶으시면 수출신용보험도 있고요."),
(L, "¿Y quién ofrece ese seguro?", "그 보험은 어디서 해 줘요?"),
(N, "Hay compañías privadas y una pública, de apoyo a la exportación. Si quiere, le paso los contactos.", "민간 보험사도 있고, 수출 지원용 공공 기관도 하나 있어요. 원하시면 연락처를 드릴게요."),
(R, "Más adelante. Primero, que paguen el primer pedido.", "나중에요. 먼저 첫 주문 대금부터 받고요."),
(N, "(sonríe) Siempre tan prudente, Ramón. Bueno, volvamos a la póliza. Puedo proponer la renovación por un año, a Euríbor más uno coma nueve.", "(웃으며) 여전히 신중하시네요, 라몬. 자, 한도 얘기로 돌아가죠. 1년 갱신, 유리보 + 1.9%로 올려 볼게요."),
(R, "El año pasado era Euríbor más uno coma seis.", "작년엔 유리보 + 1.6%였어요."),
(N, "El año pasado tenían menos stock y más beneficio.", "작년엔 재고가 적고 이익이 더 많았잖아요."),
(R, "Y el año pasado no teníamos un cliente en México.", "그리고 작년엔 멕시코 고객도 없었죠."),
(N, "Todavía no lo tienen, Ramón.", "아직 없잖아요, 라몬."),
(R, "Por eso te pido uno coma siete. Si en marzo hay pedido firmado, hablamos otra vez.", "그래서 1.7%를 요청하는 거예요. 3월에 서명된 주문이 생기면 다시 얘기하고요."),
(N, "(piensa) Uno coma ocho. Y me mandan una valoración actualizada del stock antes del día veinte.", "(생각하다가) 1.8%. 그리고 20일 전에 재고 평가 최신본을 보내 주세요."),
(R, "Uno coma ocho, y la valoración antes del veinte. De acuerdo.", "1.8%, 그리고 20일 전까지 평가서. 좋아요."),
(N, "Perfecto. Les preparo la propuesta para el comité. Y, señor Ferrer, cuando tenga una oferta para México, llámeme. Me interesa mucho.", "좋습니다. 위원회용 제안서를 준비할게요. 그리고 페레르 씨, 멕시코 견적이 나오면 전화 주세요. 아주 관심 있어요."),
(L, "Lo haré. Muchas gracias por el consejo.", "그럴게요. 조언 정말 감사합니다."),
(N, "De nada. Para eso estamos. Y Ramón... (baja la voz) esta vez, que paguen por adelantado, ¿eh?", "천만에요. 그러라고 있는 거죠. 그리고 라몬… (목소리를 낮추며) 이번엔 선불로 받으세요, 네?"),
(R, "(muy serio) Esta vez sí.", "(아주 진지하게) 이번엔 그럴 거예요."),

("#", "Escena 3 · 10:20 · De vuelta, en el coche", "장면 3 · 오전 10시 20분 · 돌아오는 차 안"),
(None, "El coche sale de Castellón. Durante unos minutos nadie habla. Al final, Lucas rompe el silencio.", "차가 카스테욘을 빠져나온다. 몇 분 동안 아무도 말하지 않는다. 결국 루카스가 침묵을 깬다."),
(L, "¿Qué ha querido decir con «esta vez»?", "'이번엔'이라는 게 무슨 뜻이었어요?"),
(R, "Lo que ha dicho. Ni más ni menos.", "말한 그대로요. 그 이상도 이하도 아니고."),
(L, "Ramón, si hay algo que debo saber antes de hablar con México, prefiero saberlo ahora.", "라몬, 멕시코와 얘기하기 전에 알아야 할 게 있다면 지금 알고 싶어요."),
(R, "Lo sabrás. Pero no me corresponde a mí contarlo. Es una historia de la familia.", "알게 될 거예요. 하지만 내가 말할 일은 아니에요. 가족의 이야기니까."),
(L, "¿Y tú no eres de la familia?", "라몬은 가족 아니에요?"),
(R, "(sonríe por primera vez) Llevo veinticinco años con ellos. Soy de la familia para los números, no para los secretos.", "(처음으로 웃으며) 그 집과 25년을 함께했어요. 숫자에 관해선 가족이지만, 비밀에 관해선 아니에요."),
(L, "Entendido. Entonces, hablemos de números. Si hago una oferta para México, ¿qué condiciones necesitas tú?", "알겠어요. 그럼 숫자 얘기를 하죠. 제가 멕시코에 견적을 내면 어떤 조건이 필요해요?"),
(R, "Tres. Primera: un anticipo del treinta por ciento como mínimo. Segunda: el resto, con carta de crédito confirmada. Tercera: no vendemos por debajo del coste.", "세 가지요. 첫째, 최소 30% 선수금. 둘째, 나머지는 확인 신용장. 셋째, 원가 이하로는 안 팔아요."),
(L, "¿Y cuál es el coste del Estatuario de sesenta por ciento veinte?", "에스타투아리오 60×120 원가는 얼마예요?"),
(R, "Depende de lo que metas dentro. Con el gas de este año, unos nueve euros con ochenta el metro, en fábrica. Sin transporte, sin embalaje especial, sin nada.", "뭘 포함하느냐에 따라 달라요. 올해 가스비로 공장 출고 기준 제곱미터당 9.80유로쯤이에요. 운송, 특수 포장, 아무것도 안 넣고요."),
(L, "Nueve ochenta. Y a la cadena de bricolaje se lo vendemos a...", "9.80. 그리고 DIY 체인엔 얼마에 팔아요?"),
(R, "A once cuarenta. Y BricoHogar es el veintidós por ciento de nuestras ventas en España, y paga a sesenta días. Por eso me da miedo el cuatro por ciento de Sergio. Si se lo damos, nos quedamos con casi nada.", "11.40에요. 그리고 브리코오가르는 우리 국내 매출의 22%고, 60일 뒤에 결제해요. 그래서 세르히오의 4%가 무서운 거예요. 그걸 주면 거의 남는 게 없어요."),
(L, "¿Y la placa grande?", "큰 판은요?"),
(R, "La placa grande es otra cosa. Ahí está el margen. Pero también el riesgo: si se rompe una en el barco, perdemos lo que ganamos con diez.", "큰 판은 얘기가 달라요. 거기에 마진이 있죠. 하지만 위험도 있어요. 배에서 한 장 깨지면 열 장 팔아 번 걸 잃어요."),
(None, "Suena el móvil de Lucas. Un mensaje de WhatsApp con una nota de voz. Prefijo +52.", "루카스의 휴대폰이 울린다. 음성 메시지가 담긴 왓츠앱 메시지. 국가번호 +52."),
(L, "Es ella. La clienta de Monterrey. ¿Te importa si lo pongo en alto?", "그 사람이에요. 몬테레이 고객. 스피커로 틀어도 괜찮아요?"),
(R, "Ponlo. Así lo oímos los dos.", "틀어요. 둘 다 듣게."),
(G, "(nota de voz) Buenos días, licenciado. Bueno, allá ya es mediodía, ¿verdad? Le aviso que llegaron las muestras. Seis cajas, todo perfecto, nada roto.", "(음성 메시지) 안녕하세요, 선생님. 아, 거기는 벌써 점심때죠? 샘플 도착했다고 알려 드려요. 여섯 상자, 다 완벽해요, 깨진 거 하나 없어요."),
(G, "(nota de voz) Las placas grandes están preciosas. Mi ingeniero quiere hacer unas pruebas y tiene varias preguntas técnicas.", "(음성 메시지) 큰 판들이 정말 예뻐요. 우리 엔지니어가 테스트를 몇 가지 해 보고 싶어 하고 기술적인 질문도 여러 개 있어요."),
(G, "(nota de voz) ¿Podemos hacer una videollamada el miércoles? A las nueve de la mañana de aquí, que son las cuatro de la tarde allá, ¿no?", "(음성 메시지) 수요일에 화상 통화 할 수 있을까요? 여기 시간 오전 9시, 거기는 오후 4시죠?"),
(G, "(nota de voz) Ah, y gracias por las fichas técnicas. Se nota que alguien allá conoce México. Saludos.", "(음성 메시지) 아, 그리고 기술 사양서 고마워요. 거기 누군가 멕시코를 잘 아는 분이 있나 봐요. 그럼 이만."),
(None, "Lucas guarda el móvil. Ramón mantiene los ojos en la carretera.", "루카스가 휴대폰을 집어넣는다. 라몬은 도로에서 눈을 떼지 않는다."),
(R, "Siete horas de diferencia. Las nueve de allí son las cuatro de aquí. Ha calculado bien.", "시차 7시간. 거기 9시면 여기 4시. 계산 잘했네요."),
(L, "Ha llegado todo bien. Y quiere hablar el miércoles.", "다 잘 도착했대요. 그리고 수요일에 얘기하고 싶대요."),
(R, "Ya lo he oído. Y las fichas técnicas, ¿de quién eran?", "들었어요. 그런데 기술 사양서는 누가 만든 거예요?"),
(L, "De Amparo. Las hizo el jueves por la noche.", "암파로요. 목요일 밤에 만들었어요."),
(R, "(asiente despacio) Eso no lo esperaba.", "(천천히 고개를 끄덕이며) 그건 예상 못 했네요."),
(L, "Yo tampoco.", "저도요."),
(R, "Amparo hizo un plan de exportación hace dos años. ¿Lo sabías?", "암파로가 2년 전에 수출 계획서를 만들었어요. 알고 있었어요?"),
(L, "Me lo contó el jueves.", "목요일에 얘기해 줬어요."),
(R, "Era bueno. Yo le dije a Vicente que lo aprobara.", "좋은 계획이었어요. 나는 비센테한테 승인하라고 했고요."),
(L, "¿Y por qué no lo aprobó?", "그런데 왜 승인 안 했어요?"),
(R, "Una cosa, Lucas. El miércoles te van a pedir precio. Es lo que hacen siempre.", "하나만요, 루카스. 수요일에 가격을 물을 거예요. 늘 그러니까."),
(L, "Lo sé.", "알아요."),
(R, "Pues no digas ningún número que no hayas hablado antes conmigo. Ni uno.", "그럼 나랑 먼저 얘기하지 않은 숫자는 하나도 말하지 마요. 단 하나도."),
(L, "¿Y si me presionan?", "압박하면요?"),
(R, "Si te presionan, dices que el precio depende del volumen y del puerto de destino. Eso es verdad. Y no compromete a nada.", "압박하면 가격은 물량과 도착 항구에 따라 달라진다고 해요. 사실이고, 아무것도 약속하는 게 아니니까."),
(L, "«Depende del volumen y del puerto de destino». Me lo apunto.", "'물량과 도착 항구에 따라 달라진다.' 적어 둘게요."),
(R, "Con la cabeza, Lucas. Con la cabeza.", "머리로요, 루카스. 머리로."),
]

